css:
.openstratsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2435;
    background: linear-gradient(165deg, #f4f6fb 0%, #e9edf6 100%);
    border-radius: 18px;
}

.openstratsim-container * {
    box-sizing: border-box;
}

.openstratsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14213d 0%, #233a63 55%, #2f4d7e 100%);
    color: #f3f6fc;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 33, 61, 0.32);
    border-bottom: 3px solid #c9a44a;
}

.openstratsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.openstratsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e6cf90;
    background: rgba(201, 164, 74, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.openstratsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dbe3f2;
}

.openstratsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3a5a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.openstratsim-period-counter #currentDay,
.openstratsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14213d;
}

.openstratsim-round-name {
    background: #dce3f1;
    color: #14213d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.openstratsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a17;
    background: #f6ecd4;
    padding: 4px 12px;
    border-radius: 999px;
}

.openstratsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.openstratsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dde3ef;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.06);
    border-top: 4px solid #2f4d7e;
}

.openstratsim-card-align { border-top-color: #1f6f54; }
.openstratsim-card-inclusion { border-top-color: #2f6fb0; }
.openstratsim-card-control { border-top-color: #14213d; }
.openstratsim-card-target { border-top-color: #c9a44a; }

.openstratsim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7796;
}

.openstratsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14213d;
}

.openstratsim-card-align .openstratsim-value { color: #1f6f54; }
.openstratsim-card-inclusion .openstratsim-value { color: #2f6fb0; }
.openstratsim-card-control .openstratsim-value { color: #14213d; }
.openstratsim-card-target .openstratsim-value { color: #a87f1f; }

.openstratsim-sublabel {
    font-size: 0.75rem;
    color: #7a86a4;
    line-height: 1.35;
}

.openstratsim-target-hit .openstratsim-value { color: #1f6f54; }
.openstratsim-target-miss .openstratsim-value { color: #c0392b; }

.openstratsim-gauges {
    display: grid;
    grid-template-columns: 1fr 1.4fr;
    gap: 14px;
    margin-bottom: 18px;
}

.openstratsim-leak {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde3ef;
    border-left: 5px solid #2f6fb0;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3a5a;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.05);
}

.openstratsim-leak #leakDisplay {
    font-size: 1.05rem;
    color: #1f6f54;
    letter-spacing: 0.3px;
}

.openstratsim-leak-low { border-left-color: #1f6f54; }
.openstratsim-leak-low #leakDisplay { color: #1f6f54; }
.openstratsim-leak-med { border-left-color: #c9a44a; }
.openstratsim-leak-med #leakDisplay { color: #a87f1f; }
.openstratsim-leak-high { border-left-color: #c0392b; }
.openstratsim-leak-high #leakDisplay { color: #c0392b; }

.openstratsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14213d;
    color: #eef2fa;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.92rem;
}

.openstratsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e6cf90;
}

.openstratsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a44a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.05);
}

.openstratsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.openstratsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14213d;
    margin-bottom: 6px;
}

.openstratsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34405c;
}

.openstratsim-briefing-text strong { color: #1f6f54; }
.openstratsim-briefing-text em { color: #8a5a17; font-style: italic; }

.openstratsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde3ef;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.06);
}

.openstratsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14213d;
    border-bottom: 2px solid #e9edf6;
    padding-bottom: 8px;
}

.openstratsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243352;
    margin: 14px 0 6px;
}

.openstratsim-container select,
.openstratsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2cbe0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8faff;
    color: #1b2435;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.openstratsim-container select:focus,
.openstratsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f4d7e;
    box-shadow: 0 0 0 3px rgba(47, 77, 126, 0.16);
}

.openstratsim-container select option {
    background-color: #ffffff;
    color: #1b2435;
}

.openstratsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f4d7e;
}

.openstratsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f4d7e;
    margin-top: 4px;
}

.openstratsim-range-readout span:last-child {
    color: #1f6f54;
    font-weight: 800;
}

.openstratsim-hint {
    font-size: 0.8rem;
    color: #7a86a4;
    margin-top: 4px;
    line-height: 1.4;
}

.openstratsim-matrix {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.openstratsim-matrix-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f7fc;
    border: 1px solid #dde6f2;
    border-radius: 9px;
    padding: 8px 12px;
}

.openstratsim-matrix-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #243352;
}

.openstratsim-matrix-row select {
    width: 230px;
    flex: 0 0 230px;
}

.openstratsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.openstratsim-container .btn-primary {
    background: linear-gradient(135deg, #14213d 0%, #2f4d7e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(20, 33, 61, 0.28);
    color: #f3f6fc;
}

.openstratsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.openstratsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c2cbe0;
    color: #6a7796;
}

.openstratsim-coach {
    background: #14213d;
    color: #eef2fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 33, 61, 0.24);
    border-left: 5px solid #c9a44a;
}

.openstratsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6cf90;
    margin-bottom: 8px;
}

.openstratsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.openstratsim-coach-body strong { color: #f0d99a; }
.openstratsim-coach-body em { color: #f2c4ad; font-style: italic; }

.openstratsim-history,
.openstratsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde3ef;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.06);
}

.openstratsim-history h3,
.openstratsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14213d;
}

.openstratsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243352;
}

.openstratsim-container table#usfHistoryTable th {
    background: #eef2fa;
    color: #14213d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6deee;
}

.openstratsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
}

.openstratsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fd;
}

.openstratsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .openstratsim-container {
        padding: 14px;
    }
    .openstratsim-header h1 {
        font-size: 1.7rem;
    }
    .openstratsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .openstratsim-value {
        font-size: 2rem;
    }
    .openstratsim-clock {
        margin-left: 0;
    }
    .openstratsim-period-counter {
        font-size: 0.88rem;
    }
    .openstratsim-gauges {
        grid-template-columns: 1fr;
    }
    .openstratsim-leak,
    .openstratsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .openstratsim-matrix-row {
        flex-wrap: wrap;
    }
    .openstratsim-matrix-row select {
        width: 100%;
        flex: 1 1 100%;
    }
    .openstratsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (dark-on-light for the framework's white modal) ===== */
.openstratsim-cm { text-align: center; color: #23293a; padding: 8px 4px 4px; }
.openstratsim-cm-title { font-size: 1.05rem; font-weight: 700; color: #3a4a7a; margin-bottom: 10px; }
.openstratsim-cm-scorewrap { margin: 4px 0 6px; }
.openstratsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #3a4a7a; }
.openstratsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a7796; }
.openstratsim-cm-scorelabel { font-size: .78rem; text-transform: uppercase; letter-spacing: .05em; color: #6a7796; }
.openstratsim-cm-grade { font-size: 1.3rem; font-weight: 700; color: #23293a; margin: 6px 0; }
.openstratsim-cm-badges { margin: 8px 0 12px; }
.openstratsim-cm-badge { display: inline-block; padding: 5px 12px; border-radius: 999px; font-size: .82rem; font-weight: 700; }
.openstratsim-cm-badge-ok { background: #dbe6fb; color: #274690; border: 1px solid #3a4a7a; }
.openstratsim-cm-badge-fail { background: #f7d9d5; color: #8f2418; border: 1px solid #c0392b; }
.openstratsim-cm-badge-warn { background: #fdf0d6; color: #8a5a12; border: 1px solid #d59a2c; }
.openstratsim-cm-kpis { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin: 10px 0; }
.openstratsim-cm-kpi { background: #f1f3f9; border: 1px solid #dbe0ec; border-radius: 10px; padding: 10px 14px; min-width: 92px; }
.openstratsim-cm-kpi-n { font-size: 1.5rem; font-weight: 800; color: #3a4a7a; }
.openstratsim-cm-kpi-l { font-size: .72rem; text-transform: uppercase; letter-spacing: .03em; color: #6a7796; }
.openstratsim-cm-insights { text-align: left; margin: 12px auto 2px; max-width: 560px; background: #f6f8fc; border: 1px solid #e2e7f2; border-radius: 10px; padding: 10px 14px; }
.openstratsim-cm-insights-h { font-weight: 700; color: #3a4a7a; margin-bottom: 6px; font-size: .9rem; }
.openstratsim-cm-insights ul { margin: 0; padding-left: 18px; }
.openstratsim-cm-insights li { color: #333a4d; font-size: .88rem; margin-bottom: 4px; }

