(function() {
    'use strict';

    class OpenStrategyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Open Strategy`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Chimiq Distribution SA, EUR).
            this.START_ALIGN = 22;        // plans nobody owns
            this.START_INCLUSION = 19;    // pulse: 19% believe targets achievable
            this.START_CONTROL = 40;      // PE board confidence, covenant headroom present
            this.START_TARGET = 28;       // gap to refinancing plan barely begun
            this.START_LEAK = 15;         // closed process, low leak risk to begin
            this.BUDGET_CAP = 600;        // EUR 600k transformation budget, in thousands
            this.WIN_COMPOSITE = 70;      // "calibrated openness" win bar

            // Concept truths.
            this.TRUE_LACK = `inclusion`;
        }

        _money(thousands) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const v = Math.round(Number(thousands) || 0);
            // EUR: EN "€600k" (symbol before); ES "600k €" (symbol after).
            return lang === `es` ? (v + `k €`) : (`€` + v + `k`);
        }

        _leakBand(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return { key: `leak_high`, label: t(`leak_high`) };
            if (v >= 35) return { key: `leak_med`, label: t(`leak_med`) };
            return { key: `leak_low`, label: t(`leak_low`) };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    align: this.START_ALIGN,
                    inclusion: this.START_INCLUSION,
                    control: this.START_CONTROL,
                    target: this.START_TARGET,
                    leak: this.START_LEAK,
                    budgetUsed: 0,
                    breached: false,
                    leaked: false,
                    alignHistory: [this.START_ALIGN],
                    inclusionHistory: [this.START_INCLUSION],
                    controlHistory: [this.START_CONTROL],
                    targetHistory: [this.START_TARGET],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    lack: `inclusion`,
                    cost: `ownership`,
                    protect: `confidentiality`,
                    candour: 60,
                    participation: `forum`,
                    hubData: `gated`,
                    marginData: `closed`,
                    pipelineData: `closed`,
                    facilitation: 180,
                    arch: `hybrid`,
                    levers: `interactive`,
                    shared: 5,
                    calib: `refclass`,
                    leak: `regate`,
                    reconcile: `withhubs`,
                    board: `calibrated`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lack = document.getElementById(`lackInput`);
                const cost = document.getElementById(`costInput`);
                const prot = document.getElementById(`protectInput`);
                const cand = document.getElementById(`candourInput`);
                if (lack) decisions.lack = lack.value;
                if (cost) decisions.cost = cost.value;
                if (prot) decisions.protect = prot.value;
                if (cand) decisions.candour = parseInt(cand.value, 10);
                if (!Number.isFinite(decisions.candour) || decisions.candour < 0 || decisions.candour > 100) {
                    warn(`warn_candour_range`); return false;
                }
            } else if (round === 2) {
                const part = document.getElementById(`participationInput`);
                const hub = document.getElementById(`hubDataInput`);
                const margin = document.getElementById(`marginDataInput`);
                const pipe = document.getElementById(`pipelineDataInput`);
                const fac = document.getElementById(`facilitationInput`);
                if (part) decisions.participation = part.value;
                if (hub) decisions.hubData = hub.value;
                if (margin) decisions.marginData = margin.value;
                if (pipe) decisions.pipelineData = pipe.value;
                if (fac) decisions.facilitation = parseFloat(fac.value);
                if (!Number.isFinite(decisions.facilitation) || decisions.facilitation < 0) {
                    warn(`warn_facilitation_negative`); return false;
                }
                if (state.domainState.budgetUsed + decisions.facilitation > this.BUDGET_CAP) {
                    warn(`warn_budget_cap`); return false;
                }
            } else if (round === 3) {
                const arch = document.getElementById(`archInput`);
                const lev = document.getElementById(`leversInput`);
                const shared = document.getElementById(`sharedInput`);
                const calib = document.getElementById(`calibInput`);
                if (arch) decisions.arch = arch.value;
                if (lev) decisions.levers = lev.value;
                if (shared) decisions.shared = parseInt(shared.value, 10);
                if (calib) decisions.calib = calib.value;
                if (!Number.isFinite(decisions.shared) || decisions.shared < 0 || decisions.shared > 8) {
                    warn(`warn_shared_range`); return false;
                }
            } else if (round === 4) {
                const leak = document.getElementById(`leakInput`);
                const rec = document.getElementById(`reconcileInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (leak) decisions.leak = leak.value;
                if (rec) decisions.reconcile = rec.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let alignD = 0, inclusionD = 0, controlD = 0, targetD = 0, leakD = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the two dimensions: Chimiq lacks INCLUSION (who makes strategy),
                // not transparency. Maximal openness on both = Common Error 1.
                switch (d.lack) {
                    case `inclusion`: inclusionD += 8; alignD += 6; coachKey = `coach_r1_inclusion`; break;
                    case `transparency`: inclusionD += 1; alignD += 1; leakD += 6; coachKey = `coach_r1_transparency`; break;
                    case `both_max`: inclusionD += 5; alignD += 3; leakD += 16; controlD -= 8; coachKey = `coach_r1_bothmax`; break;
                    case `neither`: inclusionD -= 8; alignD -= 6; coachKey = `coach_r1_neither`; break;
                }

                // Top cost of closure: ownership deficit and forecast bias are the real costs;
                // "too slow" / "leaks more" misread what closure actually does.
                if (d.cost === `ownership` || d.cost === `forecast`) {
                    alignD += 5; inclusionD += 3;
                    if (d.lack === this.TRUE_LACK) coachKey = `coach_r1_diag_sharp`;
                } else {
                    alignD -= 6; coachKey = `coach_r1_costwrong`;
                }

                // What closure protects: confidentiality (real value). "Nothing" invites Error 1;
                // "hierarchy" reproduces the disengagement.
                switch (d.protect) {
                    case `confidentiality`: controlD += 8; break;
                    case `nothing`: controlD -= 10; leakD += 10; coachKey = `coach_r1_protectnothing`; break;
                    case `hierarchy`: controlD += 2; inclusionD -= 6; coachKey = `coach_r1_hierarchy`; break;
                }

                // Candour about the participation failure vs "communicate better" (Common Error 2).
                if (d.candour >= 60) { inclusionD += 5; alignD += 3; }
                else if (d.candour <= 25) { inclusionD -= 8; alignD -= 4; coachKey = `coach_r1_lowcandour`; }

                summaryKey = (d.lack === this.TRUE_LACK && (d.cost === `ownership` || d.cost === `forecast`) && d.protect === `confidentiality`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Participation architecture + disclosure matrix under the governance constraint.
                switch (d.participation) {
                    case `forum`: inclusionD += 8; alignD += 7; controlD += 3; coachKey = `coach_r2_forum`; break;
                    case `jam_gated`: inclusionD += 10; alignD += 5; leakD += 8; coachKey = `coach_r2_jamgated`; break;
                    case `jam_open`: inclusionD += 11; alignD += 4; leakD += 22; controlD -= 10; coachKey = `coach_r2_jamopen`; break;
                    case `closed`: inclusionD -= 10; alignD -= 6; controlD += 2; coachKey = `coach_r2_closed`; break;
                }

                // Disclosure matrix. Correct: hub data open/gated (builds ownership),
                // margin-by-customer and M&A pipeline CLOSED (governance directive + covenant).
                // Hub-level cost & growth: gated to managers is ideal; open is acceptable-but-risky;
                // closed wastes the ownership lever.
                if (d.hubData === `gated`) { inclusionD += 6; alignD += 3; controlD += 3; }
                else if (d.hubData === `open`) { inclusionD += 4; alignD += 2; leakD += 6; }
                else { inclusionD -= 6; coachKey = `coach_r2_hubclosed`; }

                // Margin-by-customer must NOT be open (board-sensitive; competitor poaching).
                if (d.marginData === `open`) { leakD += 18; controlD -= 12; coachKey = `coach_r2_marginopen`; }
                else if (d.marginData === `gated`) { leakD += 6; controlD -= 2; }
                else { controlD += 5; }

                // M&A pipeline must be CLOSED (moves the share price; directive after poaching).
                if (d.pipelineData === `open`) { leakD += 20; controlD -= 14; coachKey = `coach_r2_pipelineopen`; }
                else if (d.pipelineData === `gated`) { leakD += 10; controlD -= 6; }
                else { controlD += 5; }

                // Facilitation spend: the engine of genuine participation; too little = thin inclusion.
                spend += d.facilitation;
                if (d.facilitation >= 150) { inclusionD += 6; alignD += 3; }
                else if (d.facilitation >= 80) { inclusionD += 3; alignD += 2; }
                else { inclusionD -= 4; coachKey = `coach_r2_underfund`; }

                const matrixSafe = d.marginData !== `open` && d.pipelineData !== `open`;
                if (matrixSafe && d.participation !== `closed` && d.participation !== `jam_open`) coachKey = `coach_r2_calibrated`;
                summaryKey = (matrixSafe && (d.participation === `forum` || d.participation === `jam_gated`)) ? `sum_r2_good` : ((d.marginData === `open` || d.pipelineData === `open`) ? `sum_r2_leak` : `sum_r2_weak`);
            } else if (round === 3) {
                // Dashboard as a management-control system (Common Errors 3 & 4).
                switch (d.arch) {
                    case `hybrid`: alignD += 8; inclusionD += 6; controlD += 6; coachKey = `coach_r3_hybrid`; break;
                    case `bsc`: alignD += 6; inclusionD += 2; controlD += 6; coachKey = `coach_r3_bsc`; break;
                    case `okr`: alignD += 4; inclusionD += 7; controlD += 2; coachKey = `coach_r3_okr`; break;
                    case `control`: alignD -= 8; inclusionD -= 10; controlD += 5; coachKey = `coach_r3_control`; break;
                }

                // Simons' levers: interactive + diagnostic beats diagnostic-only (Error 3).
                switch (d.levers) {
                    case `interactive`: alignD += 7; inclusionD += 6; controlD += 3; break;
                    case `diagnostic`: alignD -= 6; inclusionD -= 8; controlD += 4; coachKey = `coach_r3_diagnostic`; break;
                    case `beliefs`: alignD -= 4; controlD -= 8; coachKey = `coach_r3_beliefs`; break;
                }

                // Shared vs board-only split. 4-6 shared (of 6-8) is the calibrated band:
                // enough to build ownership, with covenant-sensitive measures kept board-only.
                if (d.shared >= 4 && d.shared <= 6) { inclusionD += 6; alignD += 3; }
                else if (d.shared >= 7) { inclusionD += 4; leakD += 10; controlD -= 8; coachKey = `coach_r3_alltransparent`; }
                else if (d.shared <= 1) { inclusionD -= 8; controlD += 2; coachKey = `coach_r3_allboard`; }
                else { inclusionD += 2; alignD += 1; }

                // Calibration rule against the 11% forecast bias.
                switch (d.calib) {
                    case `refclass`: alignD += 6; targetD += 10; controlD += 5; break;
                    case `topdown`: alignD -= 4; inclusionD -= 6; targetD += 6; coachKey = `coach_r3_calibtopdown`; break;
                    case `none`: targetD -= 8; controlD -= 6; coachKey = `coach_r3_calibnone`; break;
                }

                summaryKey = ((d.arch === `hybrid` || d.arch === `bsc` || d.arch === `okr`) && d.levers === `interactive` && d.calib === `refclass` && d.shared >= 4 && d.shared <= 6) ? `sum_r3_good` : ((d.arch === `control` || d.levers === `diagnostic`) ? `sum_r3_control` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recovery: leak response + target reconciliation + board stance.
                // Leak is an architecture problem, not a comms problem (Common Error from tree).
                ds.leaked = true;
                switch (d.leak) {
                    case `regate`: controlD += 10; leakD -= 18; alignD += 2; coachKey = `coach_r4_regate`; break;
                    case `press`: controlD -= 6; leakD += 6; coachKey = `coach_r4_press`; break;
                    case `reclose`: controlD += 6; inclusionD -= 14; alignD -= 10; leakD -= 12; coachKey = `coach_r4_reclose`; break;
                }

                // Reconcile the 4% shortfall WITH the hub directors, not over them (Common Error 5).
                switch (d.reconcile) {
                    case `withhubs`: targetD += 16; alignD += 6; inclusionD += 5; controlD += 5; coachKey = (d.leak === `regate`) ? `coach_r4_withhubs` : coachKey; break;
                    case `impose`: targetD += 12; inclusionD -= 14; alignD -= 8; coachKey = `coach_r4_impose`; break;
                    case `accept`: inclusionD += 4; targetD -= 10; controlD -= 14; ds.breached = true; coachKey = `coach_r4_accept`; break;
                }

                // Board stance: defend calibrated openness against both extremes.
                switch (d.board) {
                    case `calibrated`: controlD += 8; alignD += 5; coachKey = (d.reconcile === `withhubs` && d.leak === `regate`) ? `coach_r4_calibrated` : coachKey; break;
                    case `cave_chair`: inclusionD -= 12; alignD -= 8; controlD += 4; coachKey = `coach_r4_cavechair`; break;
                    case `cave_ceo`: inclusionD -= 12; alignD -= 6; coachKey = `coach_r4_caveceo`; break;
                }

                // Conviction nudges alignment.
                alignD += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.leak === `regate` && d.reconcile === `withhubs` && d.board === `calibrated`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));

            // Apply deltas, clamped 0-100.
            ds.align = Math.max(0, Math.min(100, ds.align + alignD));
            ds.inclusion = Math.max(0, Math.min(100, ds.inclusion + inclusionD));
            ds.control = Math.max(0, Math.min(100, ds.control + controlD));
            ds.target = Math.max(0, Math.min(100, ds.target + targetD));
            ds.leak = Math.max(0, Math.min(100, ds.leak + leakD));

            // High residual leak risk erodes control (the bank prices it in).
            if (ds.leak >= 60) ds.control = Math.max(0, ds.control - 4);

            ds.alignHistory.push(Math.round(ds.align));
            ds.inclusionHistory.push(Math.round(ds.inclusion));
            ds.controlHistory.push(Math.round(ds.control));
            ds.targetHistory.push(Math.round(ds.target));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            const composite = Math.round(ds.align * 0.30 + ds.inclusion * 0.25 + ds.control * 0.25 + ds.target * 0.20);

            // v1.1.0 FIX — persist the composite where the grading/reporting layer reads it
            // (express_resolveDomainScore -> domainState.performance.overallScore), every period.
            ds.performance = { overallScore: composite };

            return {
                period: state.currentPeriod,
                align: Math.round(ds.align),
                alignDelta: Math.round(alignD),
                inclusion: Math.round(ds.inclusion),
                inclusionDelta: Math.round(inclusionD),
                control: Math.round(ds.control),
                controlDelta: Math.round(controlD),
                target: Math.round(ds.target),
                targetDelta: Math.round(targetD),
                leak: Math.round(ds.leak),
                composite: composite,
                score: composite,
                overallScore: composite,
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
