        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.alignHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                openStratChart: {
                    labels: labels,
                    datasets: [
