        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const align = Math.round(ds.align);
            const inclusion = Math.round(ds.inclusion);
            const control = Math.round(ds.control);
            const target = Math.round(ds.target);
            const leak = Math.round(ds.leak);

            const composite = Math.round(align * 0.30 + inclusion * 0.25 + control * 0.25 + target * 0.20);
            const calibrated = composite >= this.WIN_COMPOSITE && inclusion >= 55 && control >= 55 && leak < 50;
            const radical = leak >= 55 || control < 35;
            const reclosed = inclusion < 35;

            let gradeKey = `grade_nobody`;
            if (calibrated && composite >= 80) gradeKey = `grade_calibrated`;
            else if (calibrated) gradeKey = `grade_opened`;
            else if (radical) gradeKey = `grade_backfire`;
            else if (reclosed) gradeKey = `grade_reclosed`;
            else if (composite >= 55) gradeKey = `grade_unbalanced`;
            const performance = window.mySimulation.t(gradeKey);

            const insights = [];
            if (calibrated) insights.push(window.mySimulation.t(`insight_calibrated`));
            else if (radical) insights.push(window.mySimulation.t(`insight_radical`));
            else if (reclosed) insights.push(window.mySimulation.t(`insight_reclosed`));
            else insights.push(window.mySimulation.t(`insight_unbalanced`));

            if (ds.breached) insights.push(window.mySimulation.t(`insight_breach`));
            if (inclusion < 40) insights.push(window.mySimulation.t(`insight_lowinclusion`));
            if (leak >= 50) insights.push(window.mySimulation.t(`insight_leak`));
            if (calibrated && target >= 52) insights.push(window.mySimulation.t(`insight_reconciled`));

            return {
                align: align,
                inclusion: inclusion,
                control: control,
                target: target,
                leak: leak,
                composite: composite,
                calibrated: calibrated,
                performance: performance,
                gradeKey: gradeKey,
                passed: calibrated,
                failed: (radical || reclosed || !!ds.breached),
                insights: insights
            };
        }

        // v1.1.0 FIX — real completion modal (score / localized grade / MET or distinct-failure
        // badge / KPI strip / insights). Replaces the framework's generic fallback.
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            const s = summary || {};
            const score = Number.isFinite(s.composite) ? s.composite : 0;
            const grade = s.performance || t(s.gradeKey || `grade_nobody`);
            const passed = !!s.passed;
            const failed = !!s.failed;
            const k = (v) => Math.round(v != null ? v : 0);
            let badge;
            if (passed) {
                badge = `<span class="openstratsim-cm-badge openstratsim-cm-badge-ok">\u2713 ` + t(`cm_met`) + `</span>`;
            } else if (failed) {
                badge = `<span class="openstratsim-cm-badge openstratsim-cm-badge-fail">\u2715 ` + t(`cm_fail`) + `</span>`;
            } else {
                badge = `<span class="openstratsim-cm-badge openstratsim-cm-badge-warn">\u2022 ` + t(`cm_missed`) + `</span>`;
            }
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightHtml = insights.length
                ? `<div class="openstratsim-cm-insights"><div class="openstratsim-cm-insights-h">` + t(`cm_insights`) + `</div><ul>` + insights.map((x) => `<li>` + x + `</li>`).join(``) + `</ul></div>`
                : ``;
            return `
                <div class="openstratsim-cm">
                    <div class="openstratsim-cm-title">` + t(`cm_title`) + `</div>
                    <div class="openstratsim-cm-scorewrap">
                        <div class="openstratsim-cm-score">` + score + `<span class="openstratsim-cm-score-max">/100</span></div>
                        <div class="openstratsim-cm-scorelabel">` + t(`cm_score_of`) + `</div>
                    </div>
                    <div class="openstratsim-cm-grade">` + grade + `</div>
                    <div class="openstratsim-cm-badges">` + badge + `</div>
                    <div class="openstratsim-cm-kpis">
                        <div class="openstratsim-cm-kpi"><div class="openstratsim-cm-kpi-n">` + k(s.align) + `</div><div class="openstratsim-cm-kpi-l">` + t(`cm_align`) + `</div></div>
                        <div class="openstratsim-cm-kpi"><div class="openstratsim-cm-kpi-n">` + k(s.inclusion) + `</div><div class="openstratsim-cm-kpi-l">` + t(`cm_inclusion`) + `</div></div>
                        <div class="openstratsim-cm-kpi"><div class="openstratsim-cm-kpi-n">` + k(s.control) + `</div><div class="openstratsim-cm-kpi-l">` + t(`cm_control`) + `</div></div>
                        <div class="openstratsim-cm-kpi"><div class="openstratsim-cm-kpi-n">` + k(s.target) + `</div><div class="openstratsim-cm-kpi-l">` + t(`cm_target`) + `</div></div>
                    </div>
                    ` + insightHtml + `
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
