            if (ds.leak >= 55) return window.mySimulation.t(`hint_leak`);
            if (ds.inclusion < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_inclusion`);
            if (ds.control < 35) return window.mySimulation.t(`hint_control`);
            if (state.currentPeriod >= 3 && ds.target < 35) return window.mySimulation.t(`hint_target`);
            const composite = ds.align * 0.30 + ds.inclusion * 0.25 + ds.control * 0.25 + ds.target * 0.20;
            if (composite >= this.WIN_COMPOSITE && ds.inclusion >= 55 && ds.control >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
